(6, 'Pelayan', 'pelayan', 'Mencatat dan mengirim pesanan dine in.', 1, 0, '2026-09-29 01:32:04', '2026-09-29 01:57:30'),
(7, 'Dapur', 'dapur', 'Melihat dan menyelesaikan status pesanan di dapur.', 1, 0, '2026-09-29 01:32:04', '2026-09-29 01:57:30');
